const fn = new Function(code + "\nreturn { isUser, parseWith, handleApi };");
const { isUser, parseWith, handleApi } = fn();
if (isUser({ id: "u1", email: "a@b.co" }) !== true) throw new Error("Minimal valid user accepted.");
if (isUser({ id: "u1", email: "a@b.co", name: "Ada" }) !== true) throw new Error("Optional name present is fine.");
if (isUser({ id: 7, email: "a@b.co" }) !== false) throw new Error("Numeric id must fail.");
if (isUser({ id: "u1", email: "nope" }) !== false) throw new Error("Email without @ must fail.");
if (isUser(["u1", "a@b.co"]) !== false) throw new Error("Arrays are not users.");
if (isUser(null) !== false) throw new Error("null is not a user.");

const fn = new Function(code + "\nreturn { isUser, parseWith, handleApi };");
const { isUser, parseWith, handleApi } = fn();
const good = parseWith({ id: "u1", email: "a@b.co" }, isUser, null);
if (good.ok !== true || good.value.email !== "a@b.co") throw new Error("Valid input flows through as { ok: true, value }.");
const bad = parseWith("junk", isUser, "default");
if (bad.ok !== false || bad.fallback !== "default") throw new Error("Invalid input returns { ok: false, fallback }.");

const fn = new Function(code + "\nreturn { isUser, parseWith, handleApi };");
const { isUser, parseWith, handleApi } = fn();
if (handleApi({ ok: true, data: "tasks" }) !== "tasks") throw new Error("Success returns the data.");
if (handleApi({ ok: false, status: 503 }) !== "HTTP 503") throw new Error("Failure returns 'HTTP ' + status.");
